-- Phase 2: Question Bank Seed Data
-- 96 questions across 8 security domains with NIST 800-53 mappings

-- Domain 1: Access Control (AC family) - 12 questions
INSERT INTO public.assessment_questions (domain_id, domain_name, question_text, help_text, control_id, response_type, risk_weight, order_index, finding_template, remediation_template) VALUES
('access_control', 'Access Control', 'Do all users have unique login credentials (no shared accounts)?', 'Each person should have their own username and password to ensure accountability.', 'AC-2', 'yes_no_partial', 9, 1, 'Shared accounts are in use, preventing individual accountability and increasing security risk.', 'Implement individual user accounts for all personnel. Disable or remove shared accounts.'),
('access_control', 'Access Control', 'Is there a formal process for granting system access to new users?', 'This includes documented approval workflows before access is provisioned.', 'AC-2', 'yes_no_partial', 8, 2, 'No formal access provisioning process exists, risking unauthorized access.', 'Establish a documented access request and approval workflow with management authorization.'),
('access_control', 'Access Control', 'Are user access rights reviewed at least annually?', 'Regular reviews ensure users only have access they need for their current role.', 'AC-2(3)', 'yes_no_partial', 7, 3, 'User access rights are not regularly reviewed, potentially leaving excessive permissions.', 'Implement annual access reviews with documented evidence of review and remediation actions.'),
('access_control', 'Access Control', 'Is access promptly removed when employees leave the organization?', 'Access should be disabled within 24 hours of separation.', 'AC-2(3)', 'yes_no_partial', 10, 4, 'Terminated user accounts are not promptly disabled, creating security vulnerabilities.', 'Implement offboarding procedures that disable access within 24 hours of employee separation.'),
('access_control', 'Access Control', 'Are users required to use strong passwords (8+ characters, complexity)?', 'Strong passwords include uppercase, lowercase, numbers, and special characters.', 'AC-2', 'yes_no_partial', 8, 5, 'Weak password policies allow easily guessable credentials.', 'Enforce password complexity requirements: minimum 8 characters with mixed case, numbers, and symbols.'),
('access_control', 'Access Control', 'Is multi-factor authentication (MFA) enabled for remote access?', 'MFA requires something you know (password) plus something you have (phone/token).', 'AC-17', 'yes_no_partial', 9, 6, 'Remote access lacks multi-factor authentication, increasing breach risk.', 'Implement MFA for all remote access connections using authenticator apps or hardware tokens.'),
('access_control', 'Access Control', 'Are privileged/admin accounts limited to personnel who require them?', 'Admin access should follow least privilege principles.', 'AC-6', 'yes_no_partial', 9, 7, 'Excessive privileged access increases risk of accidental or malicious system damage.', 'Review and reduce privileged access to only personnel with documented business need.'),
('access_control', 'Access Control', 'Do systems automatically lock after a period of inactivity?', 'Screen locks prevent unauthorized access to unattended workstations.', 'AC-11', 'yes_no_partial', 6, 8, 'Systems do not auto-lock, allowing unauthorized access to unattended workstations.', 'Configure automatic screen lock after 15 minutes of inactivity on all workstations.'),
('access_control', 'Access Control', 'Are unsuccessful login attempts limited before account lockout?', 'This prevents brute-force password attacks.', 'AC-7', 'yes_no_partial', 8, 9, 'No account lockout policy exists, enabling brute-force password attacks.', 'Implement account lockout after 5 failed login attempts with 30-minute lockout duration.'),
('access_control', 'Access Control', 'Is remote access to systems controlled and monitored?', 'Remote connections should be authorized, encrypted, and logged.', 'AC-17', 'yes_no_partial', 8, 10, 'Remote access is not properly controlled or monitored.', 'Implement VPN or secure remote access solution with logging and access controls.'),
('access_control', 'Access Control', 'Are default passwords changed on all systems and devices?', 'Factory default credentials are publicly known and easily exploited.', 'AC-2', 'yes_no_partial', 9, 11, 'Default passwords remain on systems, creating easily exploitable vulnerabilities.', 'Inventory all systems and change default credentials before deployment.'),
('access_control', 'Access Control', 'Is there separation of duties for critical functions?', 'No single person should control all aspects of a critical process.', 'AC-5', 'yes_no_partial', 7, 12, 'Lack of separation of duties increases fraud and error risk.', 'Implement role-based access with separation of duties for financial and administrative functions.'),

-- Domain 2: Awareness & Training (AT family) - 12 questions
('awareness_training', 'Security Awareness & Training', 'Do all employees receive security awareness training upon hire?', 'Initial training should cover security policies, acceptable use, and threat awareness.', 'AT-2', 'yes_no_partial', 7, 1, 'New employees do not receive security awareness training, leaving them vulnerable to threats.', 'Implement mandatory security awareness training as part of employee onboarding.'),
('awareness_training', 'Security Awareness & Training', 'Is security awareness training provided at least annually?', 'Regular refresher training keeps security top of mind.', 'AT-2', 'yes_no_partial', 7, 2, 'Annual security training is not conducted, leading to degraded security awareness.', 'Establish annual security awareness training program with completion tracking.'),
('awareness_training', 'Security Awareness & Training', 'Does training cover how to identify phishing emails?', 'Phishing is the most common attack vector for organizations.', 'AT-2(1)', 'yes_no_partial', 8, 3, 'Employees lack phishing awareness training, increasing successful attack likelihood.', 'Add phishing identification and reporting procedures to security training curriculum.'),
('awareness_training', 'Security Awareness & Training', 'Are employees trained on proper handling of sensitive data?', 'This includes classification, storage, transmission, and disposal procedures.', 'AT-2', 'yes_no_partial', 8, 4, 'Employees are not trained on sensitive data handling, risking data breaches.', 'Include data classification and handling procedures in security awareness training.'),
('awareness_training', 'Security Awareness & Training', 'Is there training on acceptable use of company systems?', 'Covers personal use restrictions, prohibited activities, and monitoring notice.', 'AT-2', 'yes_no_partial', 6, 5, 'No acceptable use training exists, leading to policy violations and security risks.', 'Develop and deliver acceptable use policy training with signed acknowledgment.'),
('awareness_training', 'Security Awareness & Training', 'Are IT staff trained on their specific security responsibilities?', 'Role-based training for technical staff on secure configurations and incident response.', 'AT-3', 'yes_no_partial', 8, 6, 'IT staff lack role-specific security training, increasing misconfiguration risk.', 'Provide specialized security training for IT personnel on secure administration.'),
('awareness_training', 'Security Awareness & Training', 'Is training completion tracked and documented?', 'Records should show who completed training and when.', 'AT-4', 'yes_no_partial', 6, 7, 'Training completion is not tracked, preventing verification of compliance.', 'Implement learning management system or tracking mechanism for training records.'),
('awareness_training', 'Security Awareness & Training', 'Are employees trained on social engineering threats?', 'Covers pretexting, tailgating, and other manipulation techniques.', 'AT-2(1)', 'yes_no_partial', 7, 8, 'Employees are not trained to recognize social engineering attacks.', 'Add social engineering awareness module to security training program.'),
('awareness_training', 'Security Awareness & Training', 'Is there training on mobile device security?', 'Covers securing smartphones, tablets, and working remotely.', 'AT-2', 'yes_no_partial', 6, 9, 'Mobile device security training is lacking, increasing mobile-related risks.', 'Include mobile device security best practices in awareness training.'),
('awareness_training', 'Security Awareness & Training', 'Do employees know how to report security incidents?', 'Clear reporting procedures should be communicated to all staff.', 'AT-2', 'yes_no_partial', 8, 10, 'Employees do not know how to report security incidents, delaying response.', 'Communicate incident reporting procedures and contact information to all employees.'),
('awareness_training', 'Security Awareness & Training', 'Is there a process to update training for new threats?', 'Training content should be updated to address emerging threats.', 'AT-2', 'yes_no_partial', 6, 11, 'Security training content is outdated and does not address current threats.', 'Establish process to review and update training content at least annually.'),
('awareness_training', 'Security Awareness & Training', 'Are phishing simulations conducted to test employee awareness?', 'Simulated attacks help measure and improve security awareness.', 'AT-2(1)', 'yes_no_partial', 7, 12, 'No phishing simulations are conducted to test employee awareness.', 'Implement quarterly phishing simulation program with targeted follow-up training.'),

-- Domain 3: Audit & Accountability (AU family) - 12 questions
('audit_accountability', 'Audit & Accountability', 'Are security-relevant events logged on critical systems?', 'Includes login attempts, privilege changes, and system modifications.', 'AU-2', 'yes_no_partial', 9, 1, 'Security events are not logged, preventing detection and investigation of incidents.', 'Enable security event logging on all critical systems including servers and network devices.'),
('audit_accountability', 'Audit & Accountability', 'Do audit logs capture who, what, when, and where for events?', 'Logs should include user ID, action, timestamp, and source.', 'AU-3', 'yes_no_partial', 8, 2, 'Audit logs lack sufficient detail for effective investigation.', 'Configure logging to capture user identity, action performed, timestamp, and source IP.'),
('audit_accountability', 'Audit & Accountability', 'Are audit logs protected from unauthorized modification?', 'Logs should be write-protected or stored on separate systems.', 'AU-9', 'yes_no_partial', 9, 3, 'Audit logs can be modified, allowing attackers to cover their tracks.', 'Implement write-once logging or forward logs to a protected central log server.'),
('audit_accountability', 'Audit & Accountability', 'Are logs retained for at least 90 days?', 'Retention allows investigation of incidents discovered after the fact.', 'AU-11', 'yes_no_partial', 7, 4, 'Insufficient log retention prevents investigation of past incidents.', 'Configure log retention for minimum 90 days, with 1 year recommended for compliance.'),
('audit_accountability', 'Audit & Accountability', 'Are logs reviewed regularly for suspicious activity?', 'Regular review helps detect security incidents early.', 'AU-6', 'yes_no_partial', 8, 5, 'Logs are not reviewed, allowing incidents to go undetected.', 'Establish weekly log review process or implement automated alerting for anomalies.'),
('audit_accountability', 'Audit & Accountability', 'Is there centralized log collection from multiple systems?', 'SIEM or log aggregation provides comprehensive visibility.', 'AU-6(1)', 'yes_no_partial', 7, 6, 'Logs are scattered across systems, hindering correlation and analysis.', 'Implement centralized log collection using SIEM or log management solution.'),
('audit_accountability', 'Audit & Accountability', 'Are failed login attempts logged and monitored?', 'Failed logins may indicate brute-force attacks or compromised credentials.', 'AU-2', 'yes_no_partial', 8, 7, 'Failed login attempts are not monitored, missing potential attack indicators.', 'Enable logging of failed authentication attempts with alerting for patterns.'),
('audit_accountability', 'Audit & Accountability', 'Is there alerting for critical security events?', 'Real-time alerts enable rapid response to threats.', 'AU-5', 'yes_no_partial', 8, 8, 'No alerting exists for critical events, delaying incident detection.', 'Configure alerts for critical events: admin logins, policy changes, security failures.'),
('audit_accountability', 'Audit & Accountability', 'Are system clocks synchronized for accurate timestamps?', 'NTP synchronization ensures log correlation across systems.', 'AU-8', 'yes_no_partial', 6, 9, 'System clocks are not synchronized, preventing accurate log correlation.', 'Configure NTP time synchronization on all systems to authoritative time source.'),
('audit_accountability', 'Audit & Accountability', 'Is there capacity management for audit log storage?', 'Prevents loss of logs due to storage exhaustion.', 'AU-4', 'yes_no_partial', 6, 10, 'Log storage capacity is not monitored, risking log loss.', 'Monitor log storage capacity with alerts and automated archival or rotation.'),
('audit_accountability', 'Audit & Accountability', 'Are privileged user actions specifically logged?', 'Admin activities require enhanced monitoring.', 'AU-2', 'yes_no_partial', 8, 11, 'Privileged user actions are not specifically tracked.', 'Enable enhanced logging for all administrative and privileged account activities.'),
('audit_accountability', 'Audit & Accountability', 'Can audit logs be correlated with user identities?', 'Logs should tie actions to specific individuals for accountability.', 'AU-3', 'yes_no_partial', 7, 12, 'Logs cannot be correlated to user identities, limiting accountability.', 'Ensure logging includes authenticated user identity, not just system accounts.'),

-- Domain 4: Configuration Management (CM family) - 12 questions
('configuration_management', 'Configuration Management', 'Is there a documented baseline configuration for systems?', 'Standard configurations ensure consistent security settings.', 'CM-2', 'yes_no_partial', 8, 1, 'No baseline configurations exist, leading to inconsistent security settings.', 'Develop and document standard secure baseline configurations for each system type.'),
('configuration_management', 'Configuration Management', 'Are systems kept up to date with security patches?', 'Regular patching addresses known vulnerabilities.', 'CM-3', 'yes_no_partial', 10, 2, 'Systems are not regularly patched, leaving known vulnerabilities exploitable.', 'Implement patch management process with monthly patching cycle for critical updates.'),
('configuration_management', 'Configuration Management', 'Is there a change management process for system modifications?', 'Changes should be requested, approved, tested, and documented.', 'CM-3', 'yes_no_partial', 8, 3, 'No change management process exists, risking uncontrolled system changes.', 'Establish change management process with request, approval, testing, and documentation.'),
('configuration_management', 'Configuration Management', 'Are unnecessary services and ports disabled?', 'Reducing attack surface by disabling unused functionality.', 'CM-7', 'yes_no_partial', 8, 4, 'Unnecessary services increase attack surface and vulnerability exposure.', 'Audit systems to identify and disable unnecessary services, protocols, and ports.'),
('configuration_management', 'Configuration Management', 'Is software installation restricted to authorized personnel?', 'Prevents installation of unauthorized or malicious software.', 'CM-11', 'yes_no_partial', 7, 5, 'Users can install unauthorized software, risking malware and compliance issues.', 'Restrict software installation rights to IT administrators only.'),
('configuration_management', 'Configuration Management', 'Is there an inventory of hardware assets?', 'You cannot protect what you do not know exists.', 'CM-8', 'yes_no_partial', 7, 6, 'No hardware inventory exists, preventing comprehensive security management.', 'Create and maintain hardware asset inventory with owner and location information.'),
('configuration_management', 'Configuration Management', 'Is there an inventory of software applications?', 'Identifies all software requiring updates and licensing.', 'CM-8', 'yes_no_partial', 7, 7, 'No software inventory exists, preventing license compliance and patch management.', 'Create and maintain software inventory including versions and license information.'),
('configuration_management', 'Configuration Management', 'Are configuration changes tested before production deployment?', 'Testing prevents outages and security issues from untested changes.', 'CM-3', 'yes_no_partial', 7, 8, 'Changes are deployed without testing, risking system instability and security issues.', 'Require testing in non-production environment before deploying configuration changes.'),
('configuration_management', 'Configuration Management', 'Is antivirus/anti-malware installed and current?', 'Endpoint protection is essential for detecting malware.', 'CM-3', 'yes_no_partial', 9, 9, 'Antivirus protection is missing or outdated on systems.', 'Deploy and maintain current antivirus/anti-malware on all endpoints and servers.'),
('configuration_management', 'Configuration Management', 'Are mobile devices managed and secured?', 'MDM or security policies for company mobile devices.', 'CM-2', 'yes_no_partial', 7, 10, 'Mobile devices are not managed, risking data loss if devices are lost or stolen.', 'Implement mobile device management with encryption and remote wipe capabilities.'),
('configuration_management', 'Configuration Management', 'Is there a process to decommission systems securely?', 'Includes data sanitization and disposal procedures.', 'CM-3', 'yes_no_partial', 7, 11, 'No secure decommissioning process exists, risking data exposure.', 'Establish secure decommissioning procedures with data sanitization verification.'),
('configuration_management', 'Configuration Management', 'Are system configurations backed up?', 'Enables recovery of configurations after incidents.', 'CM-2', 'yes_no_partial', 6, 12, 'System configurations are not backed up, complicating disaster recovery.', 'Implement regular backup of system configurations with tested restoration.'),

-- Domain 5: Contingency Planning (CP family) - 12 questions
('contingency_planning', 'Contingency Planning', 'Is there a documented business continuity plan?', 'Plan for maintaining operations during and after disruptions.', 'CP-2', 'yes_no_partial', 8, 1, 'No business continuity plan exists, risking extended outages during incidents.', 'Develop business continuity plan addressing critical business functions.'),
('contingency_planning', 'Contingency Planning', 'Are critical systems and data backed up regularly?', 'Backups should occur at least daily for critical data.', 'CP-9', 'yes_no_partial', 10, 2, 'Critical data is not regularly backed up, risking permanent data loss.', 'Implement daily backup of critical systems and data with verification.'),
('contingency_planning', 'Contingency Planning', 'Are backups stored offsite or in the cloud?', 'Protects backups from local disasters affecting primary site.', 'CP-6', 'yes_no_partial', 9, 3, 'Backups are stored only on-site, vulnerable to local disasters.', 'Implement offsite or cloud backup storage with encryption in transit and at rest.'),
('contingency_planning', 'Contingency Planning', 'Are backup restorations tested regularly?', 'Untested backups may fail when needed most.', 'CP-4', 'yes_no_partial', 8, 4, 'Backup restorations are not tested, leaving recovery capability unverified.', 'Conduct quarterly backup restoration tests with documented results.'),
('contingency_planning', 'Contingency Planning', 'Is there a disaster recovery plan?', 'Technical plan for recovering IT systems after major incidents.', 'CP-2', 'yes_no_partial', 8, 5, 'No disaster recovery plan exists for IT systems.', 'Develop disaster recovery plan with RTOs and RPOs for critical systems.'),
('contingency_planning', 'Contingency Planning', 'Are recovery time objectives (RTOs) defined?', 'Maximum acceptable downtime for critical systems.', 'CP-2', 'yes_no_partial', 7, 6, 'No recovery time objectives are defined for critical systems.', 'Define RTOs for each critical system based on business impact analysis.'),
('contingency_planning', 'Contingency Planning', 'Is the continuity plan tested at least annually?', 'Testing validates plan effectiveness and identifies gaps.', 'CP-4', 'yes_no_partial', 7, 7, 'Continuity plan is not tested, leaving effectiveness unknown.', 'Conduct annual continuity plan exercises ranging from tabletop to full simulation.'),
('contingency_planning', 'Contingency Planning', 'Are alternate processing sites identified?', 'Location to continue operations if primary site is unavailable.', 'CP-7', 'yes_no_partial', 6, 8, 'No alternate processing capability exists for extended outages.', 'Identify alternate processing options including cloud failover capabilities.'),
('contingency_planning', 'Contingency Planning', 'Is there redundancy for critical systems?', 'Failover capability for essential business systems.', 'CP-8', 'yes_no_partial', 7, 9, 'No redundancy exists for critical systems, creating single points of failure.', 'Implement redundancy for critical systems including database and application tiers.'),
('contingency_planning', 'Contingency Planning', 'Are emergency contacts documented and current?', 'Contact list for key personnel during incidents.', 'CP-2', 'yes_no_partial', 6, 10, 'Emergency contact information is not documented or current.', 'Maintain current emergency contact list with quarterly verification.'),
('contingency_planning', 'Contingency Planning', 'Is there a plan for prolonged power outages?', 'UPS and generator capabilities for critical systems.', 'CP-8', 'yes_no_partial', 6, 11, 'No provisions exist for prolonged power outages.', 'Assess power backup needs and implement UPS with generator backup as needed.'),
('contingency_planning', 'Contingency Planning', 'Are backup encryption keys stored securely and accessible?', 'Keys needed to restore encrypted backups must be available.', 'CP-9', 'yes_no_partial', 8, 12, 'Backup encryption keys are not properly managed, risking inability to restore.', 'Implement secure key management with key escrow for backup encryption.'),

-- Domain 6: Incident Response (IR family) - 12 questions
('incident_response', 'Incident Response', 'Is there a documented incident response plan?', 'Procedures for detecting, responding to, and recovering from incidents.', 'IR-1', 'yes_no_partial', 9, 1, 'No incident response plan exists, leading to ad-hoc and ineffective responses.', 'Develop incident response plan covering detection, containment, eradication, and recovery.'),
('incident_response', 'Incident Response', 'Are incident response roles and responsibilities defined?', 'Clear ownership for incident handling activities.', 'IR-2', 'yes_no_partial', 8, 2, 'Incident response roles are not defined, causing confusion during incidents.', 'Define and document incident response team roles with contact information.'),
('incident_response', 'Incident Response', 'Is there a process to report security incidents?', 'Clear escalation path for potential security events.', 'IR-6', 'yes_no_partial', 8, 3, 'No incident reporting process exists, delaying response to security events.', 'Establish incident reporting procedures with clear escalation paths.'),
('incident_response', 'Incident Response', 'Are security incidents documented and tracked?', 'Record keeping for analysis and compliance.', 'IR-5', 'yes_no_partial', 7, 4, 'Incidents are not tracked, preventing trend analysis and lessons learned.', 'Implement incident tracking system to document all security incidents.'),
('incident_response', 'Incident Response', 'Is the incident response plan tested regularly?', 'Tabletop exercises or simulations validate readiness.', 'IR-3', 'yes_no_partial', 7, 5, 'Incident response plan is not tested, leaving team unprepared.', 'Conduct annual incident response exercises including tabletop scenarios.'),
('incident_response', 'Incident Response', 'Are lessons learned documented after incidents?', 'Post-incident review improves future response.', 'IR-4', 'yes_no_partial', 6, 6, 'No post-incident reviews are conducted, missing improvement opportunities.', 'Conduct post-incident reviews within 2 weeks of incident closure.'),
('incident_response', 'Incident Response', 'Is there capability to contain security incidents?', 'Ability to isolate affected systems to prevent spread.', 'IR-4', 'yes_no_partial', 9, 7, 'No incident containment capabilities exist, allowing incidents to spread.', 'Develop containment procedures including network isolation and account disabling.'),
('incident_response', 'Incident Response', 'Are there procedures for preserving evidence?', 'Evidence collection for investigation and potential legal action.', 'IR-4', 'yes_no_partial', 7, 8, 'No evidence preservation procedures exist, compromising investigations.', 'Document evidence preservation procedures aligned with legal requirements.'),
('incident_response', 'Incident Response', 'Is there a process for notifying affected parties?', 'Breach notification for customers, regulators, or partners.', 'IR-6', 'yes_no_partial', 8, 9, 'No breach notification process exists, risking regulatory non-compliance.', 'Develop breach notification procedures meeting regulatory requirements.'),
('incident_response', 'Incident Response', 'Are third-party incident response resources identified?', 'External expertise for major incidents (forensics, legal, PR).', 'IR-7', 'yes_no_partial', 6, 10, 'No external incident response resources are identified.', 'Identify and establish relationships with external IR firms, legal counsel.'),
('incident_response', 'Incident Response', 'Is there 24/7 capability to respond to critical incidents?', 'After-hours response for severe security events.', 'IR-4', 'yes_no_partial', 7, 11, 'No after-hours incident response capability exists.', 'Establish on-call rotation or managed security services for 24/7 coverage.'),
('incident_response', 'Incident Response', 'Are incident response playbooks available for common scenarios?', 'Step-by-step guides for ransomware, phishing, data breach, etc.', 'IR-1', 'yes_no_partial', 7, 12, 'No incident response playbooks exist for common scenarios.', 'Develop playbooks for common incidents: ransomware, phishing, unauthorized access.'),

-- Domain 7: System & Communications Protection (SC family) - 12 questions
('system_protection', 'System & Communications Protection', 'Is network traffic protected by a firewall?', 'Firewall controls inbound and outbound network access.', 'SC-7', 'yes_no_partial', 10, 1, 'No firewall protection exists, exposing systems to network attacks.', 'Deploy and configure firewall to control network traffic with deny-by-default rules.'),
('system_protection', 'System & Communications Protection', 'Is sensitive data encrypted when transmitted over networks?', 'TLS/SSL for data in transit over internal and external networks.', 'SC-8', 'yes_no_partial', 9, 2, 'Sensitive data is transmitted unencrypted, risking interception.', 'Implement TLS encryption for all sensitive data transmission.'),
('system_protection', 'System & Communications Protection', 'Is sensitive data encrypted when stored (at rest)?', 'Disk encryption, database encryption, or file-level encryption.', 'SC-28', 'yes_no_partial', 9, 3, 'Sensitive data is stored unencrypted, risking exposure if media is lost/stolen.', 'Implement encryption for sensitive data at rest using full-disk or database encryption.'),
('system_protection', 'System & Communications Protection', 'Are wireless networks secured with strong encryption?', 'WPA2/WPA3 with strong passwords for WiFi networks.', 'SC-8', 'yes_no_partial', 8, 4, 'Wireless networks use weak or no encryption, enabling eavesdropping.', 'Configure wireless networks with WPA3 or WPA2-Enterprise with strong passwords.'),
('system_protection', 'System & Communications Protection', 'Is there network segmentation between different security zones?', 'Separate networks for servers, users, guests, and sensitive systems.', 'SC-7', 'yes_no_partial', 8, 5, 'Flat network allows lateral movement after initial compromise.', 'Implement network segmentation with VLANs and firewall rules between zones.'),
('system_protection', 'System & Communications Protection', 'Are public-facing systems isolated from internal networks?', 'DMZ architecture for web servers and other public services.', 'SC-7', 'yes_no_partial', 8, 6, 'Public-facing systems are not isolated, enabling direct internal network access.', 'Implement DMZ for public-facing systems with restricted internal access.'),
('system_protection', 'System & Communications Protection', 'Is email protected with spam and malware filtering?', 'Email security gateway for inbound and outbound protection.', 'SC-7', 'yes_no_partial', 8, 7, 'Email lacks spam and malware filtering, enabling phishing attacks.', 'Deploy email security solution with spam, malware, and phishing protection.'),
('system_protection', 'System & Communications Protection', 'Are web browsing activities filtered for malicious content?', 'Web proxy or DNS filtering for malicious sites.', 'SC-7', 'yes_no_partial', 7, 8, 'No web filtering exists, allowing access to malicious websites.', 'Implement web filtering to block known malicious sites and categories.'),
('system_protection', 'System & Communications Protection', 'Is intrusion detection/prevention deployed?', 'IDS/IPS monitors for attack patterns in network traffic.', 'SC-7', 'yes_no_partial', 7, 9, 'No intrusion detection exists, missing network-based attacks.', 'Deploy intrusion detection/prevention system for critical network segments.'),
('system_protection', 'System & Communications Protection', 'Are cryptographic keys managed securely?', 'Key generation, storage, rotation, and destruction procedures.', 'SC-12', 'yes_no_partial', 8, 10, 'Cryptographic keys are not properly managed, risking key compromise.', 'Implement key management procedures including secure storage and rotation.'),
('system_protection', 'System & Communications Protection', 'Is there protection against denial-of-service attacks?', 'DDoS protection for public-facing services.', 'SC-5', 'yes_no_partial', 6, 11, 'No DDoS protection exists for public-facing services.', 'Implement DDoS protection through CDN or cloud-based mitigation service.'),
('system_protection', 'System & Communications Protection', 'Are systems hardened according to security benchmarks?', 'CIS Benchmarks or STIG configurations for operating systems.', 'SC-2', 'yes_no_partial', 7, 12, 'Systems are not hardened, leaving default insecure configurations.', 'Apply CIS Benchmark or STIG hardening guidelines to all systems.'),

-- Domain 8: Physical & Environmental Protection (PE family) - 12 questions
('physical_security', 'Physical & Environmental Protection', 'Is physical access to server rooms/data centers controlled?', 'Key card, combination lock, or other access control.', 'PE-3', 'yes_no_partial', 9, 1, 'Server room lacks physical access controls, enabling unauthorized access.', 'Implement access control for server rooms with key card or combination lock.'),
('physical_security', 'Physical & Environmental Protection', 'Is there a visitor management process?', 'Sign-in, escort requirements, and badge issuance for visitors.', 'PE-3', 'yes_no_partial', 6, 2, 'No visitor management process exists, allowing unescorted access.', 'Implement visitor sign-in, badge issuance, and escort requirements.'),
('physical_security', 'Physical & Environmental Protection', 'Are workstations secured to prevent theft?', 'Cable locks or secured workspaces for laptops and equipment.', 'PE-4', 'yes_no_partial', 5, 3, 'Workstations are not physically secured, enabling theft.', 'Deploy cable locks for laptops and secure mounting for desktop equipment.'),
('physical_security', 'Physical & Environmental Protection', 'Is there video surveillance of sensitive areas?', 'CCTV monitoring of entrances, server rooms, and critical areas.', 'PE-6', 'yes_no_partial', 6, 4, 'No video surveillance exists for sensitive areas.', 'Install CCTV cameras for entrances and sensitive areas with 30-day retention.'),
('physical_security', 'Physical & Environmental Protection', 'Are environmental controls in place for server rooms?', 'Temperature, humidity, and water detection for IT equipment.', 'PE-14', 'yes_no_partial', 7, 5, 'Inadequate environmental controls risk equipment failure.', 'Implement HVAC, humidity control, and environmental monitoring for server rooms.'),
('physical_security', 'Physical & Environmental Protection', 'Is there fire detection and suppression?', 'Smoke detectors and fire suppression appropriate for IT equipment.', 'PE-13', 'yes_no_partial', 7, 6, 'Inadequate fire protection for IT equipment.', 'Install smoke detection and appropriate fire suppression for server areas.'),
('physical_security', 'Physical & Environmental Protection', 'Are sensitive documents secured when not in use?', 'Locked cabinets or clean desk policy for sensitive papers.', 'PE-4', 'yes_no_partial', 6, 7, 'Sensitive documents are left unsecured, risking exposure.', 'Implement clean desk policy with locked storage for sensitive documents.'),
('physical_security', 'Physical & Environmental Protection', 'Is there uninterruptible power supply (UPS) for critical systems?', 'Battery backup for graceful shutdown during power outages.', 'PE-11', 'yes_no_partial', 7, 8, 'No UPS protection for critical systems, risking data corruption.', 'Deploy UPS for servers and networking equipment with adequate runtime.'),
('physical_security', 'Physical & Environmental Protection', 'Are physical access logs maintained and reviewed?', 'Records of who accessed controlled areas and when.', 'PE-8', 'yes_no_partial', 6, 9, 'Physical access is not logged, preventing security investigations.', 'Implement physical access logging with periodic review of access records.'),
('physical_security', 'Physical & Environmental Protection', 'Is there a process for disposing of sensitive media?', 'Secure destruction of hard drives, papers, and storage media.', 'PE-16', 'yes_no_partial', 8, 10, 'Sensitive media is not securely disposed, risking data recovery.', 'Implement media sanitization procedures with verification and documentation.'),
('physical_security', 'Physical & Environmental Protection', 'Are equipment maintenance records maintained?', 'Documentation of who serviced equipment and what was done.', 'PE-2', 'yes_no_partial', 5, 11, 'Equipment maintenance is not documented.', 'Maintain maintenance logs for critical IT equipment.'),
('physical_security', 'Physical & Environmental Protection', 'Is cabling protected from damage and interception?', 'Protected pathways and secured network cabling.', 'PE-9', 'yes_no_partial', 5, 12, 'Network cabling is exposed and vulnerable to damage or tampering.', 'Route network cables through protected pathways with secured access points.');